// Build one plain-text alert from whatever the Error Trigger gives us.
// The trigger has TWO output shapes and they share almost no fields:
//   - a node failed mid-run  -> $json.execution.{id,url,mode,lastNodeExecuted,error.message}
//   - the trigger itself died -> $json.trigger.{mode,error.{node,message,timestamp}}
// Reading only the first one is why most error workflows go quiet exactly when
// the schedule stops firing. Handle both.

const w = $json.workflow || {};
const e = $json.execution || null;
const t = $json.trigger || null;

let source, failedAt, mode, execId, url, raw;

if (e) {
  source   = 'EXECUTION FAILED';
  failedAt = e.lastNodeExecuted;
  mode     = e.mode;
  execId   = e.id;
  url      = e.url;
  raw      = (e.error && e.error.message) || '';
} else if (t) {
  source   = 'TRIGGER FAILED';
  failedAt = t.error && t.error.node;
  mode     = t.mode;
  raw      = (t.error && t.error.message) || '';
} else {
  source = 'WORKFLOW FAILED';
  raw    = 'The error trigger fired with a payload this alert does not recognise.';
}

// Never let a stack trace or a long API body blow past Telegram's 4096-char limit.
const message = String(raw || 'no message').slice(0, 1200);
const line = (label, value) => (value ? label + ': ' + value + '\n' : '');

const text =
  source + '\n\n' +
  line('workflow', w.name) +
  line('failed at', failedAt) +
  line('mode', mode) +
  line('execution', execId) +
  '\n' + message +
  (url ? '\n\n' + url : '');

return [{ json: { text } }];
